export const positionsCss=".positions-page{min-height:100vh}.positions-page header{gap:20px}.positions-page .positions-intro{color:#99adc3;font-size:13px;margin:10px 0 0}.positions-page .intro{align-items:end;gap:20px}.positions-page .intro h2{font-weight:600}.positions-summary{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin:24px 0 15px}.positions-summary article{padding:19px 21px;border:1px solid #243342;border-radius:9px;background:linear-gradient(125deg,#111e2a,#0d141d)}.positions-summary article span{font:9px ui-monospace,monospace;letter-spacing:1.1px;color:#8ba0b7}.positions-summary strong{font:29px ui-monospace,monospace;display:block;margin-top:12px;color:#e5eef7}.positions-summary article:first-child strong{color:#63decb}.positions-policy{font-size:11px;color:#8096ae;margin:15px 0 25px;line-height:1.8}.positions-notice{padding:13px 17px;border:1px solid #72592e;border-radius:7px;background:#241e13;color:#e6c68e;font-size:12px;line-height:1.7}.positions-notice[hidden]{display:none}.position-group{margin-bottom:24px}.position-group .panel-head{padding:20px;align-items:flex-start}.position-group h3{font-size:15px;line-height:1.6}.position-group .group-id{font:9px ui-monospace,monospace;color:#6e879e;margin-top:5px}.position-group .group-counts{display:flex;flex-wrap:wrap;justify-content:flex-end;gap:8px;padding-top:3px}.position-group .group-counts .open-count{color:#60dfd0;border-color:#256d65;background:#102b2a}.positions-page table{min-width:1050px;table-layout:auto}.positions-page td{padding:16px 14px;vertical-align:top;font:11px ui-monospace,monospace}.positions-page th{padding:11px 14px}.positions-page td small{font-size:9px;line-height:1.8;max-width:190px;white-space:normal;overflow-wrap:anywhere}.positions-page td:first-child{min-width:116px}.positions-page td:nth-child(5){min-width:150px}.positions-page td:last-child{min-width:142px}.position-symbol{font-size:13px;color:#e3edf7;letter-spacing:.4px}.position-group tr.is-open{background:#0e2026}.position-group tr.is-open td:first-child{border-left:2px solid #53d6bf;padding-left:12px}.position-group tr:hover{background:#16232f}.position-status{font:9px ui-monospace,monospace;border:1px solid #34495f;border-radius:4px;padding:4px 6px;display:inline-block;color:#a7bbcf}.position-status.open{border-color:#267c70;color:#6ee4d1;background:#10302d}.position-status.unknown{border-color:#735b36;color:#efc779}.quote-price{font-size:15px;display:block;color:#d7e6f4;font-variant-numeric:tabular-nums}.quote-badge{font:8px ui-monospace,monospace;color:#a0aebf;display:inline-block;margin:7px 0 3px;letter-spacing:.4px}.quote-badge.live{color:#6ce3c8}.quote-badge.live:before{content:'● ';font-size:7px}.quote-badge.old{color:#d2b482}.position-group .panel-foot{line-height:1.8}.pnl-primary{font-size:13px;display:block}.positions-empty{padding:40px;text-align:center;color:#8ea6bc;font-size:13px}.positions-page .health.error{color:#eeadad}.positions-page .header-actions{margin-left:auto}.positions-page footer{padding-top:10px;line-height:1.8}@media(max-width:1100px){.positions-summary{grid-template-columns:repeat(2,minmax(0,1fr))}.positions-page .intro{align-items:flex-start;flex-direction:column}.position-group .panel-head{flex-direction:column}.position-group .group-counts{justify-content:flex-start}}@media(max-width:700px){.positions-page .positions-intro{font-size:12px}.positions-summary{gap:9px}.positions-summary article{padding:15px}.positions-summary article span{font-size:8px}.positions-summary strong{font-size:25px}.positions-page .intro h2{font-size:22px}}\n";
export const positionsJs="'use strict';\nconst $=id=>document.getElementById(id),array=x=>Array.isArray(x)?x:[],money=n=>Number.isFinite(n)?n.toLocaleString('en-IN',{minimumFractionDigits:2,maximumFractionDigits:2}):'—';\nconst time=n=>{const t=typeof n==='number'?n:Date.parse(n);return Number.isFinite(t)?new Date(t).toLocaleString('en-GB',{timeZone:'Asia/Kolkata',day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false})+' IST':'—';};\nconst node=(tag,text,cls)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=String(text);if(cls)e.className=cls;return e;};\nlet data=null,inFlight=false,disconnected=false;\nfunction cell(row,text,small,cls){const td=node('td');td.append(node('span',text,cls));if(small)td.append(node('small',small));row.append(td);return td;}\nfunction quoteLive(p){return !disconnected&&p.quote?.current&&Date.now()-Date.parse(p.quote.observedAt)<=15000&&Date.now()-Date.parse(p.quote.sourceTime)<=60000;}\nfunction pnlCell(row,p){const td=node('td'),gross=p.status==='open'&&!quoteLive(p)?null:p.grossPnl,net=p.status==='open'&&!quoteLive(p)?null:p.netPnl;\n if(p.unknownOutcome){td.append(node('span','UNKNOWN','position-status unknown'),node('small','Missing execution coverage; P&L unresolved'));}\n else{td.append(node('span',Number.isFinite(net)?money(net):Number.isFinite(gross)?money(gross):'—','pnl-primary '+(Number.isFinite(net)?net>=0?'green':'red':'')));td.append(node('small',Number.isFinite(net)?(p.status==='open'?'Est. net · gross ':'Recorded net · gross ')+money(gross):Number.isFinite(gross)?'Gross only · net unavailable':p.status==='open'?'Waiting for a fresh mark':'No recorded result'));}\n row.append(td);return td;\n}\nfunction render(){if(!data)return;const groups=$('strategy-positions'),scrolls=new Map([...groups.querySelectorAll('[data-strategy]')].map(e=>[e.dataset.strategy,e.querySelector('.table-scroll').scrollLeft]));\n for(const [id,key] of [['open-count','open'],['closed-count','closed'],['strategy-count','strategies'],['unknown-count','unknown']])$(id).textContent=data.summary[key];\n const fragment=document.createDocumentFragment();for(const g of array(data.strategies)){\n  const section=node('section',undefined,'panel position-group');section.dataset.strategy=g.id;const heading=node('div',undefined,'panel-head'),title=node('div');title.append(node('h3',g.name),node('div',g.id,'group-id'));const counts=node('div',undefined,'group-counts');counts.append(node('span',g.summary.open+' OPEN','chip open-count'),node('span',g.summary.closed+' CLOSED','chip'));if(g.summary.unknown)counts.append(node('span',g.summary.unknown+' UNKNOWN','chip amber'));heading.append(title,counts);section.append(heading);\n  const scroll=node('div',undefined,'table-scroll'),table=node('table');table.setAttribute('aria-label',g.name+' paper positions');const head=node('thead'),hr=node('tr');for(const label of ['INSTRUMENT / SESSION','POSITION','QTY','ENTRY / IST','MARKET PRICE / INR','STOP / TARGET','EXIT / IST','P&L / INR']){const th=node('th',label);th.scope='col';hr.append(th);}head.append(hr);table.append(head);const body=node('tbody');\n  for(const p of array(g.positions)){const row=node('tr',undefined,p.status==='open'?'is-open':'');row.dataset.position=p.status;cell(row,p.symbol,p.session,'position-symbol');const status=cell(row,p.status.toUpperCase(),p.side.toUpperCase(),'position-status '+p.status);cell(row,p.quantity,p.assetClass==='MCX_FUTURE'?'Lots · multiplier '+p.multiplier:'Shares');cell(row,money(p.entry),time(p.entryAt));const q=cell(row,money(p.quote?.price),undefined,'quote-price');q.dataset.observed=p.quote?.observedAt??'';q.dataset.source=p.quote?.sourceTime??'';q.dataset.live=String(Boolean(p.quote?.current));q.append(node('span',quoteLive(p)?'LIVE SNAPSHOT':p.quote?.price!==null?'LAST RECORDED · NOT LIVE':'PRICE UNAVAILABLE','quote-badge '+(quoteLive(p)?'live':'old')),node('small',time(p.quote?.sourceTime??p.quote?.observedAt)));cell(row,money(p.stop)+' / '+money(p.target),'Stop / target');cell(row,money(p.exit),p.status==='closed'?time(p.exitAt)+(p.exitReason?' · '+p.exitReason.replaceAll('_',' '):''):'Open position');const pnl=pnlCell(row,p);if(p.status==='open')pnl.classList.add('pnl-live');body.append(row);}\n  table.append(body);scroll.append(table);section.append(scroll);const known=g.summary.closed-g.summary.closedWithoutKnownNet;section.append(node('div','Recorded net subtotal: '+(known?'INR '+money(g.summary.knownRealizedNet):'—')+' · '+known+' closed positions with known net'+(g.summary.closedWithoutKnownNet?' · '+g.summary.closedWithoutKnownNet+' closed positions without known net':'')+' · Independent strategy account','panel-foot'));fragment.append(section);\n }\n if(!fragment.childNodes.length)fragment.append(node('div','No entered open or closed paper positions yet. Scanner candidates and historical backtests do not appear here.','panel positions-empty'));groups.replaceChildren(fragment);for(const el of groups.querySelectorAll('[data-strategy]'))el.querySelector('.table-scroll').scrollLeft=scrolls.get(el.dataset.strategy)??0;\n $('last-update').textContent='Updated '+time(data.servedAt);const errors=[...array(data.errors),...(data.quoteFeed.error?['Quote feed: '+data.quoteFeed.error]:[])];$('notice').hidden=!errors.length;$('notice').textContent=errors.join(' · ');updateStatus();\n}\nfunction updateStatus(){const state=$('feed-status');state.classList.toggle('error',disconnected);$('connection').textContent=disconnected?'DISCONNECTED':data?.errors?.length?'PARTIAL DATA':data?.quoteFeed.phase==='market_snapshots'?'PAPER POSITION MONITOR':'OUTSIDE MARKET / RECORDED MARKS';$('feed-note').textContent=disconnected?'Displayed records are cached. Prices are not current; retrying automatically.':data?'All strategies · refresh every 5s · source trade timestamps interpreted as IST':'Reading recorded paper ledgers…';\n for(const q of document.querySelectorAll('[data-live=\"true\"]')){const live=!disconnected&&Date.now()-Date.parse(q.dataset.observed)<=15000&&Date.now()-Date.parse(q.dataset.source)<=60000;if(!live){const badge=q.querySelector('.quote-badge');badge.textContent='LAST RECORDED · NOT LIVE';badge.className='quote-badge old';const row=q.closest('tr'),pnl=row.querySelector('.pnl-live');if(pnl){pnl.replaceChildren(node('span','—','pnl-primary'),node('small','Waiting for a fresh mark'));}}}\n}\nasync function refresh(){if(inFlight)return;inFlight=true;$('refresh').disabled=true;try{const response=await fetch('/api/positions',{credentials:'same-origin',cache:'no-store',signal:AbortSignal.timeout(10000)});if(!response.ok)throw Error('HTTP '+response.status);const next=await response.json();if(!next.paperOnly)throw Error('Unexpected data source');data=next;disconnected=false;render();}catch{disconnected=true;updateStatus();}finally{inFlight=false;$('refresh').disabled=false;}}\n$('refresh').onclick=refresh;refresh();setInterval(refresh,5000);setInterval(updateStatus,1000);\n";
